create or replace function public.submit_quiz_attempt(p_quiz_id uuid,p_level public.jlpt_level,p_skill public.content_skill,p_answers jsonb,p_duration_seconds integer default 0) returns public.quiz_attempts language plpgsql security definer set search_path=public as $$ declare v_attempt public.quiz_attempts; v_total integer; v_correct integer; v_xp integer; v_score numeric(5,2); begin if auth.uid() is null then raise exception 'Authentication required'; end if; select count(*) into v_total from jsonb_array_elements(coalesce(p_answers,'[]'::jsonb)); if v_total=0 then raise exception 'No answers submitted'; end if; select count(*) into v_correct from jsonb_array_elements(coalesce(p_answers,'[]'::jsonb)) a join public.questions q on q.id=(a->>'questionId')::uuid where q.is_published=true and (a->>'selectedIndex')::integer=q.correct_index; v_score:=round((v_correct::numeric/v_total::numeric)*100,2); v_xp:=v_correct*10; insert into public.quiz_attempts(user_id,quiz_id,level,skill,total_questions,correct_count,score,xp_earned,duration_seconds) values(auth.uid(),p_quiz_id,p_level,p_skill,v_total,v_correct,v_score,v_xp,greatest(coalesce(p_duration_seconds,0),0)) returning * into v_attempt; insert into public.quiz_answers(attempt_id,user_id,question_id,selected_index,is_correct) select v_attempt.id,auth.uid(),(a->>'questionId')::uuid,(a->>'selectedIndex')::integer,(a->>'selectedIndex')::integer=q.correct_index from jsonb_array_elements(coalesce(p_answers,'[]'::jsonb)) a join public.questions q on q.id=(a->>'questionId')::uuid and q.is_published=true; return v_attempt; end; $$; revoke all on function public.submit_quiz_attempt(uuid,public.jlpt_level,public.content_skill,jsonb,integer) from public; grant execute on function public.submit_quiz_attempt(uuid,public.jlpt_level,public.content_skill,jsonb,integer) to authenticated;
